.btn-53,
.btn-53 *,
.btn-53 :after,
.btn-53 :before,
.btn-53:after,
.btn-53:before {
  border: 0 solid;
  box-sizing: border-box;
}

.btn-53 {
  -webkit-tap-highlight-color: transparent;
  -webkit-appearance: none; /* Override default button appearance */
  background-color: rgba(
    255,
    255,
    255,
    0.1
  ); /* Semi-transparent background for glass effect */
  backdrop-filter: blur(10px); /* Blur effect for glassmorphism */
  color: #fff; /* White text color */
  cursor: pointer;
  padding: 1.2rem 3rem;
  font-weight: 900;
  text-transform: uppercase;
  display: inline-block;
  border-radius: 999px; /* Fully rounded corners */
  position: relative;
  overflow: hidden;
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    Segoe UI, Roboto, Helvetica Neue, Arial, Noto Sans, sans-serif,
    Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol, Noto Color Emoji;
  font-size: 100%;
  line-height: 1.5;
  margin: 0;
  border: 1px solid rgba(255, 255, 255, 0.3); /* Light border for depth */
  box-shadow: 0 0 15px rgba(0, 255, 255, 0.6); /* Cyan glow */
}

/* Styles for disabled state */
.btn-53:disabled {
  cursor: default;
}

/* Focus ring for accessibility */
.btn-53:-moz-focusring {
  outline: auto;
}

.btn-53 svg {
  display: block;
  vertical-align: middle;
}

.btn-53 [hidden] {
  display: none;
}

/* Original label styling */
.btn-53 .original {
  background: #000; /* Black background */
  color: #fff; /* White color text */
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  transition: transform 0.2s cubic-bezier(0.87, 0, 0.13, 1);
}

/* Hover effect to slide up the original label */
.btn-53:hover .original {
  transform: translateY(100%);
}

/* Container for the letters, ensuring they are centered */
.btn-53 .letters {
  display: flex;
  justify-content: center;
  height: 100%;
}

/* Initial state of letters: invisible and translated for animation */
.btn-53 span {
  opacity: 0;
  transform: translateY(-100%); /* Start from above */
  transition: opacity 0.2s, transform 0.2s cubic-bezier(0.87, 0, 0.13, 1);
  transition-delay: 0.1s;
}

/* Hover state: make letters visible and move to final position */
.btn-53:hover span {
  opacity: 1;
  transform: translateY(0);
}

/* Staggered animation delays for each letter */
.btn-53:hover span:nth-child(1) {
  transition-delay: 0.1s;
}
.btn-53:hover span:nth-child(2) {
  transition-delay: 0.2s;
}
/* Continue as needed for each letter */
